var strideS = 1.1, J = 0.0006;
var dtReal = helpers.dt / 100 * strideS;
var K = params.Kst, B = params.Bd, Ke = params.kExt;
var load = 1e-6;
for (var k = 0; k < helpers.n; k++) load = Math.max(load, Math.abs(input[k]));
var on = 0.05, dur = Math.max(params.pertDur, 1) / 100;
var th = 0, w = 0, out = [];
for (var i = 0; i < helpers.n; i++) {
  var p = helpers.t[i] / 100;
  var ramp = (p >= on && p < on + dur) ? Math.sin(Math.PI * (p - on) / dur) : 0;
  var loading = Math.abs(input[i]) / load;
  /* Where the belt drags the foot to, in radians — a KINEMATIC disturbance. */
  var thExt = (params.pertAmp / 50) * 0.25 * ramp * (0.35 + 0.65 * loading);
  /* Damping is taken implicitly. Treated explicitly, this integrator needs
   * (B/J)·dt < 2, which the damping slider passes at its upper end — the
   * joint would then flip between the clamps and the torque would explode. */
  w = (w + (Ke * (thExt - th) - K * th) / J * dtReal) / (1 + (B / J) * dtReal);
  th = helpers.clamp(th + w * dtReal, -1.2, 1.2);
  out.push(th * 180 / Math.PI);
}
return out;

var strideS = 1.1;
var dtReal = helpers.dt / 100 * strideS;
var out = [];
for (var i = 0; i < helpers.n; i++) {
  var p = helpers.t[i] / 100;
  var stance = params.pkDf * Math.sin(Math.PI * helpers.clamp(p / 0.62, 0, 1));
  var pushoff = params.pkPf * Math.exp(-Math.pow((p - 0.66) / 0.05, 2));
  var swing = 0.35 * params.pkDf * Math.exp(-Math.pow((p - 0.85) / 0.10, 2));
  var thd = stance - pushoff + swing;
  var win = Math.exp(-Math.pow((p - params.tPeak / 100) / 0.13, 2));
  var tff = -(params.pkTau / 6.8) * Math.max(thd, 0) * win
          + 0.12 * Math.exp(-Math.pow((p - 0.08) / 0.05, 2));
  var dth = input[i] * Math.PI / 180;
  var prev = (i > 0 ? input[i - 1] : input[0]) * Math.PI / 180;
  var dthDot = (dth - prev) / dtReal;
  out.push((tff - params.Kst * dth - params.Bd * dthDot) * params.bodyMass);
}
return out;

