var strideS = 1.1, J = 0.0006, dtReal = helpers.dt / 100 * strideS;
var K = 4 * params.expZ, B = 0.06 * params.expZ;
var nom = [], tot = [], xs = [];
var th = 0, w = 0;
for (var i = 0; i < helpers.n; i++) {
  var p = helpers.t[i] / 100;
  var stance = 10 * Math.sin(Math.PI * helpers.clamp(p / 0.62, 0, 1));
  var pushoff = 18 * Math.exp(-Math.pow((p - 0.66) / 0.05, 2));
  var thd = stance - pushoff + 3.5 * Math.exp(-Math.pow((p - 0.85) / 0.10, 2));
  var tff = -0.228 * Math.max(thd, 0) * Math.exp(-Math.pow((p - 0.5) / 0.13, 2))
          + 0.12 * Math.exp(-Math.pow((p - 0.08) / 0.05, 2));
  var ramp = (p >= 0.05 && p < 0.30) ? Math.sin(Math.PI * (p - 0.05) / 0.25) : 0;
  var thExt = (params.expPert / 50) * 0.25 * ramp * 0.4;
  var prevTh = th;
  w = (w + (6 * (thExt - th) - K * th) / J * dtReal) / (1 + (B / J) * dtReal);
  th = helpers.clamp(th + w * dtReal, -1.2, 1.2);
  var dthDot = (th - prevTh) / dtReal;
  xs.push(helpers.t[i]);
  nom.push(tff);
  tot.push(tff - K * th - B * dthDot);
}
return { x: xs, series: [ { label: 'planned torque τ_ff', data: nom }, { label: 'commanded torque τ during the disturbance', data: tot } ] };

