for (var i = 0; i < helpers.n; i++) {
  var p = helpers.t[i] / 100;
  var stance = 10 * Math.sin(Math.PI * helpers.clamp(p / 0.62, 0, 1));
  var pushoff = 18 * Math.exp(-Math.pow((p - 0.66) / 0.05, 2));
  var a = stance - pushoff + 3.5 * Math.exp(-Math.pow((p - 0.85) / 0.10, 2));
  ang.push(a);
  tff.push(-0.155 * Math.max(a, 0) * Math.exp(-Math.pow((p - 0.5) / 0.13, 2))
         + 0.12 * Math.exp(-Math.pow((p - 0.08) / 0.05, 2)));
}
for (var j = 0; j < helpers.n; j++) {
  var prev = j > 0 ? ang[j - 1] : ang[0];
  var dRate = ((ang[j] - prev) * Math.PI / 180) / dtReal;
  var num = tff[j] + B * dRate;
  xs.push(helpers.t[j]);
  thd.push(ang[j]);
  eqa.push(helpers.clamp(ang[j] + num / params.eqKa * 180 / Math.PI, -180, 180));
  eqb.push(helpers.clamp(ang[j] + num / params.eqKb * 180 / Math.PI, -180, 180));
}
return { x: xs, series: [ { label: 'desired angle θ_d', data: thd }, { label: 'θ_eq, controller α', data: eqa }, { label: 'θ_eq, controller β', data: eqb } ] };

